package com.dunerealms.quests;
import java.sql.*;
import java.util.*;
public final class QuestStore {
 @FunctionalInterface public interface Connections{Connection open()throws SQLException;}
 public record Definition(String key,String title,String description,boolean hidden,int interval,int survive,int version){}
 public record Event(UUID id,UUID player,String key,String title,String description,String status,long assigned,long deadline,UUID worm){}
 public record Attempt(UUID id,UUID player,Definition definition){}
 public record Active(List<Event> events,long now){}
 private final Connections connections;
 public QuestStore(String url,String user,String password){if(url==null||!url.startsWith("jdbc:mysql://"))throw new IllegalArgumentException("Private MySQL settings required");connections=()->{try{Class.forName("com.mysql.cj.jdbc.Driver");}catch(ClassNotFoundException e){throw new SQLException("Driver unavailable");}Properties p=new Properties();p.setProperty("user",user);p.setProperty("password",password);p.setProperty("connectTimeout","3000");p.setProperty("socketTimeout","5000");p.setProperty("connectionTimeZone","UTC");return DriverManager.getConnection(url,p);};}
 public QuestStore(Connections c){connections=c;}
 public static long now(Connection c)throws SQLException{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)")){if(!r.next())throw new SQLException("Clock unavailable");return r.getLong(1);}}
 public void initialize()throws SQLException{try(Connection c=connections.open();Statement s=c.createStatement()){
  s.execute("CREATE TABLE IF NOT EXISTS dune_quest_definitions(quest_key VARCHAR(64) PRIMARY KEY,title VARCHAR(120) NOT NULL,description TEXT NOT NULL,engine VARCHAR(32) NOT NULL DEFAULT 'worm-survival',enabled BOOLEAN NOT NULL DEFAULT TRUE,hidden BOOLEAN NOT NULL DEFAULT TRUE,interval_seconds INT NOT NULL,survive_seconds INT NOT NULL,reward_dunemarks BIGINT NOT NULL DEFAULT 0,version INT NOT NULL DEFAULT 1,next_run_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,updated_by VARCHAR(64) NOT NULL,CONSTRAINT dune_quest_reward_zero CHECK(reward_dunemarks=0),CONSTRAINT dune_quest_interval_bounds CHECK(interval_seconds BETWEEN 3600 AND 604800),CONSTRAINT dune_quest_survive_bounds CHECK(survive_seconds BETWEEN 60 AND 1800)) ENGINE=InnoDB");
  s.execute("CREATE TABLE IF NOT EXISTS dune_quest_events(id VARCHAR(36) PRIMARY KEY,definition_key VARCHAR(64) NOT NULL,definition_version INT NOT NULL,player_uuid VARCHAR(36),server_id VARCHAR(32) NOT NULL,status VARCHAR(20) NOT NULL,assigned_at BIGINT NOT NULL,deadline_at BIGINT,completed_at BIGINT,worm_uuid VARCHAR(36),reason VARCHAR(500) NOT NULL DEFAULT '',title_snapshot VARCHAR(120) NOT NULL,description_snapshot TEXT NOT NULL,INDEX dune_quest_player(player_uuid,assigned_at),INDEX dune_quest_active(status,server_id),FOREIGN KEY(definition_key) REFERENCES dune_quest_definitions(quest_key)) ENGINE=InnoDB");
  long now=now(c);try(PreparedStatement q=c.prepareStatement("INSERT IGNORE INTO dune_quest_definitions(quest_key,title,description,interval_seconds,survive_seconds,next_run_at,updated_at,updated_by) VALUES('buried-thunder','Buried Thunder','An immense sandworm has found your trail. Survive the encounter or defeat it.',3600,300,?,?, 'system')")){q.setLong(1,now+3600000);q.setLong(2,now);q.executeUpdate();}
 }}
 private static Definition definition(ResultSet r)throws SQLException{return new Definition(r.getString("quest_key"),r.getString("title"),r.getString("description"),r.getBoolean("hidden"),r.getInt("interval_seconds"),r.getInt("survive_seconds"),r.getInt("version"));}
 private static Event event(ResultSet r)throws SQLException{String player=r.getString("player_uuid"),worm=r.getString("worm_uuid");return new Event(UUID.fromString(r.getString("id")),player==null?null:UUID.fromString(player),r.getString("definition_key"),r.getString("title_snapshot"),r.getString("description_snapshot"),r.getString("status"),r.getLong("assigned_at"),r.getLong("deadline_at"),worm==null?null:UUID.fromString(worm));}
 public Attempt claimDue(UUID player,String skipReason)throws SQLException{try(Connection c=connections.open()){c.setAutoCommit(false);try{long now=now(c);Definition d;try(PreparedStatement q=c.prepareStatement("SELECT * FROM dune_quest_definitions WHERE enabled AND engine='worm-survival' AND next_run_at<=? ORDER BY next_run_at,quest_key LIMIT 1 FOR UPDATE SKIP LOCKED")){q.setLong(1,now);try(ResultSet r=q.executeQuery()){if(!r.next()){c.rollback();return null;}d=definition(r);}}
  try(PreparedStatement q=c.prepareStatement("UPDATE dune_quest_definitions SET next_run_at=? WHERE quest_key=?")){q.setLong(1,now+d.interval()*1000L);q.setString(2,d.key());q.executeUpdate();}
  UUID id=UUID.randomUUID();try(PreparedStatement q=c.prepareStatement("INSERT INTO dune_quest_events(id,definition_key,definition_version,player_uuid,server_id,status,assigned_at,title_snapshot,description_snapshot,reason) VALUES(?,?,?,?,'arrakis',?,?,?,?,?)")){q.setString(1,id.toString());q.setString(2,d.key());q.setInt(3,d.version());q.setString(4,player==null?null:player.toString());q.setString(5,player==null?"skipped":"preparing");q.setLong(6,now);q.setString(7,d.title());q.setString(8,d.description());q.setString(9,player==null?skipReason:"");q.executeUpdate();}c.commit();return new Attempt(id,player,d);
 }catch(Exception e){c.rollback();if(e instanceof SQLException sql)throw sql;throw e;}}}
 public Event assign(Attempt attempt,UUID worm)throws SQLException{try(Connection c=connections.open()){long now=now(c),deadline=now+attempt.definition().survive()*1000L;try(PreparedStatement q=c.prepareStatement("UPDATE dune_quest_events SET status='assigned',worm_uuid=?,assigned_at=?,deadline_at=? WHERE id=? AND status='preparing'")){q.setString(1,worm.toString());q.setLong(2,now);q.setLong(3,deadline);q.setString(4,attempt.id().toString());if(q.executeUpdate()!=1)throw new SQLException("Quest attempt changed");}return new Event(attempt.id(),attempt.player(),attempt.definition().key(),attempt.definition().title(),attempt.definition().description(),"assigned",now,deadline,worm);}}
 public boolean finish(UUID id,String status,String reason)throws SQLException{if(!Set.of("completed","failed","skipped").contains(status)||reason==null||reason.length()>500)throw new IllegalArgumentException("Invalid event outcome");try(Connection c=connections.open();PreparedStatement q=c.prepareStatement("UPDATE dune_quest_events SET status=?,reason=?,completed_at=? WHERE id=? AND status IN ('assigned','preparing')")){q.setString(1,status);q.setString(2,reason);q.setLong(3,now(c));q.setString(4,id.toString());return q.executeUpdate()==1;}}
 public Active active()throws SQLException{try(Connection c=connections.open();PreparedStatement q=c.prepareStatement("SELECT * FROM dune_quest_events WHERE server_id='arrakis' AND status IN ('assigned','preparing') ORDER BY assigned_at LIMIT 100");ResultSet r=q.executeQuery()){List<Event> events=new ArrayList<>();while(r.next())events.add(event(r));return new Active(events,now(c));}}
 public List<Event> player(UUID id)throws SQLException{try(Connection c=connections.open();PreparedStatement q=c.prepareStatement("SELECT * FROM dune_quest_events WHERE player_uuid=? AND deadline_at IS NOT NULL AND status IN ('assigned','completed','failed','discovered') ORDER BY assigned_at DESC LIMIT 50")){q.setString(1,id.toString());try(ResultSet r=q.executeQuery()){List<Event> events=new ArrayList<>();while(r.next())events.add(event(r));return events;}}}
 public List<Definition> definitions()throws SQLException{try(Connection c=connections.open();PreparedStatement q=c.prepareStatement("SELECT * FROM dune_quest_definitions ORDER BY quest_key");ResultSet r=q.executeQuery()){List<Definition> rows=new ArrayList<>();while(r.next())rows.add(definition(r));return rows;}}
}

